S=/tmp/claude-1000/redact; cat > $S/redact.py <<'EOF'
import json, re, sys
src, dst = sys.argv[1:3]
KEEP = "marcus-meleiro/teste-onfly"
subs = [
    (re.compile(r"Contents of /home/marcusmeleiro/\.claude/projects/[^\n]*MEMORY\.md[^\n]*\n(?:\n?- \[[^\n]*\n?)+"), "[memórias de outras sessões removidas da exportação]\n"),
    (re.compile(r"(?:\?\? [^\n]*\n)+(?:\?\? [^\n]*)?(?:\.\.\. \(truncated[^\n]*)?"), "[listagem de arquivos pessoais removida da exportação]\n"),
    (re.compile(r"<recent-project-folders>[removido]</recent-project-folders>", re.S), "<recent-project-folders>[removido]</recent-project-folders>"),
    (re.compile(r"marcus\.meleiro@[removido]\.com"), "[e-mail removido]"),
    (re.compile(r"[arquivo pessoal removido]"\n]{0,60}"), "[arquivo pessoal removido]"),
    (re.compile(r"marcus-meleiro/(?!teste-onfly)[\w.-]+"), "[repositório pessoal removido]"),
]
def clean_str(s):
    for rx, rep in subs: s = rx.sub(rep, s)
    return s
def other_remote(x):
    return isinstance(x, dict) and isinstance(x.get("remote"), str) and x["remote"] != KEEP
def walk(x):
    if isinstance(x, str): return clean_str(x)
    if isinstance(x, list): return [walk(i) for i in x if not other_remote(i)]
    if isinstance(x, dict): return {k: walk(v) for k, v in x.items() if not other_remote(v)}
    return x
with open(src, encoding="utf-8") as f, open(dst, "w", encoding="utf-8") as g:
    for line in f:
        if line.strip(): g.write(json.dumps(walk(json.loads(line)), ensure_ascii=False) + "\n")
EOF
python3 -I $S/redact.py $S/raw.jsonl $S/clean.jsonl && wc -l $S/clean.jsonl && python3 -I -c "import json,sys;[json.loads(l) for l in open(sys.argv[1])];print('json ok')" $S/clean.jsonl
for p in "[removido]" "[arquivo pessoal removido]" "[removido]" "[removido]" "[removido] [removido]" "[removido]" "[removido]" "[removido]" "marcusmeleiro/bd" "[removido]" "[removido]" "[removido]" "[removido]" "removid"; do printf "%-22s %s\n" "$p" "$(grep -c -- "$p" $S/clean.jsonl)"; done

